import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Deque;
import java.util.List;
import java.util.PriorityQueue;

public class GraphsTour {
    static String[] city = {"Ames", "Boise", "Cary", "Dover", "Erie", "Flint"};
    static List<List<int[]>> adj = new ArrayList<>();      // adj.get(u) holds {v, km}

    static void road(int u, int v, int km) {
        adj.get(u).add(new int[]{v, km});
        adj.get(v).add(new int[]{u, km});                   // undirected
    }

    public static void main(String[] args) {
        for (int i = 0; i < city.length; i++) adj.add(new ArrayList<>());
        road(0, 1, 7); road(0, 2, 9); road(0, 5, 14); road(1, 2, 10);
        road(1, 3, 15); road(2, 3, 11); road(2, 5, 2); road(3, 4, 6); road(4, 5, 9);

        // BFS: fewest roads (ignores distances)
        int[] hops = new int[city.length];
        Arrays.fill(hops, -1);
        hops[0] = 0;
        Deque<Integer> queue = new ArrayDeque<>(List.of(0));
        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int[] e : adj.get(u)) if (hops[e[0]] == -1) { hops[e[0]] = hops[u] + 1; queue.add(e[0]); }
        }

        // Dijkstra: shortest distance in km
        int[] km = new int[city.length];
        Arrays.fill(km, Integer.MAX_VALUE);
        km[0] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[1], b[1]));
        pq.add(new int[]{0, 0});
        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            if (top[1] > km[top[0]]) continue;              // stale entry
            for (int[] e : adj.get(top[0])) {
                if (km[top[0]] + e[1] < km[e[0]]) {
                    km[e[0]] = km[top[0]] + e[1];
                    pq.add(new int[]{e[0], km[e[0]]});
                }
            }
        }
        System.out.println("from Ames:   roads  km");
        for (int i = 0; i < city.length; i++) System.out.printf("  %-8s %5d %4d%n", city[i], hops[i], km[i]);
        System.out.println("Flint: 1 road away (14 km), yet the 2-road route through Cary is only 11 km");
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class GraphRepresentation {
    public static void main(String[] args) {
        int n = 5;
        int[][] edges = {{0, 1}, {0, 2}, {1, 2}, {2, 3}, {3, 1}, {3, 4}};   // directed u -> v

        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        int[][] matrix = new int[n][n];
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            matrix[e[0]][e[1]] = 1;
        }

        System.out.println("adjacency list:");
        for (int u = 0; u < n; u++) System.out.println("  " + u + " -> " + adj.get(u));
        System.out.println("adjacency matrix:");
        for (int[] row : matrix) System.out.println("  " + Arrays.toString(row));

        System.out.println("edge 3 -> 1? list: " + adj.get(3).contains(1) + " (scan of " + adj.get(3).size()
                + "), matrix: " + (matrix[3][1] == 1) + " (one cell)");
        int[] inDegree = new int[n];
        for (List<Integer> list : adj) for (int v : list) inDegree[v]++;
        for (int u = 0; u < n; u++) {
            System.out.println("  vertex " + u + ": out-degree " + adj.get(u).size() + ", in-degree " + inDegree[u]);
        }

        int bigV = 1000, bigE = 3000;
        System.out.println("sparse graph V=" + bigV + ", E=" + bigE + ": list stores " + bigE
                + " entries, matrix stores " + (bigV * bigV) + " cells");
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

public class DepthFirstSearch {
    static List<List<Integer>> adj = new ArrayList<>();
    static boolean[] visited;

    static void edge(int u, int v) { adj.get(u).add(v); adj.get(v).add(u); }

    static void dfs(int u, int depth, List<Integer> component) {
        visited[u] = true;
        component.add(u);
        System.out.println("  ".repeat(depth + 1) + "enter " + u);
        for (int v : adj.get(u)) if (!visited[v]) dfs(v, depth + 1, component);
        System.out.println("  ".repeat(depth + 1) + "leave " + u);
    }

    static List<Integer> dfsIterative(int start) {
        boolean[] seen = new boolean[adj.size()];
        List<Integer> order = new ArrayList<>();
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(start);
        while (!stack.isEmpty()) {
            int u = stack.pop();
            if (seen[u]) continue;                          // pushed twice: already handled
            seen[u] = true;
            order.add(u);
            List<Integer> nbrs = adj.get(u);
            for (int i = nbrs.size() - 1; i >= 0; i--) {    // reverse, so the first neighbour pops first
                if (!seen[nbrs.get(i)]) stack.push(nbrs.get(i));
            }
        }
        return order;
    }

    public static void main(String[] args) {
        int n = 7;
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        edge(0, 1); edge(0, 2); edge(1, 3); edge(2, 3); edge(4, 5);   // vertex 6 has no edges
        visited = new boolean[n];
        List<List<Integer>> components = new ArrayList<>();
        for (int s = 0; s < n; s++) {
            if (visited[s]) continue;
            System.out.println("new component from " + s + ":");
            List<Integer> component = new ArrayList<>();
            dfs(s, 0, component);
            components.add(component);
        }
        System.out.println(components.size() + " components: " + components);
        System.out.println("iterative DFS order from 0: " + dfsIterative(0));
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Deque;
import java.util.List;

public class BreadthFirstSearch {
    static String names = "ABCDEFGH";
    static List<List<Integer>> adj = new ArrayList<>();

    static void edge(char a, char b) {
        int u = names.indexOf(a), v = names.indexOf(b);
        adj.get(u).add(v);
        adj.get(v).add(u);
    }

    public static void main(String[] args) {
        for (int i = 0; i < names.length(); i++) adj.add(new ArrayList<>());
        edge('A', 'B'); edge('A', 'C'); edge('B', 'D'); edge('C', 'D');
        edge('C', 'E'); edge('D', 'F'); edge('E', 'G'); edge('F', 'G');   // H is isolated

        int n = names.length();
        int[] dist = new int[n], parent = new int[n];
        Arrays.fill(dist, -1);
        Arrays.fill(parent, -1);
        dist[0] = 0;
        Deque<Integer> queue = new ArrayDeque<>(List.of(0));
        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : adj.get(u)) {
                if (dist[v] != -1) continue;
                dist[v] = dist[u] + 1;          // discovered: mark now, not when dequeued
                parent[v] = u;
                queue.add(v);
            }
        }

        for (int d = 0; d <= 3; d++) {
            StringBuilder level = new StringBuilder();
            for (int v = 0; v < n; v++) if (dist[v] == d) level.append(names.charAt(v)).append(' ');
            System.out.println("distance " + d + ": " + level.toString().trim());
        }
        for (char target : new char[]{'G', 'H'}) {
            int t = names.indexOf(target);
            if (dist[t] == -1) {
                System.out.println("A -> " + target + ": unreachable");
                continue;
            }
            List<Character> path = new ArrayList<>();
            for (int v = t; v != -1; v = parent[v]) path.add(names.charAt(v));
            Collections.reverse(path);
            System.out.println("A -> " + target + ": " + path + " (" + dist[t] + " edges)");
        }
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.PriorityQueue;

public class ShortestPath {
    static String names = "SABCDT";
    static List<List<int[]>> adj = new ArrayList<>();

    static void edge(char a, char b, int w) {   // directed, weighted
        adj.get(names.indexOf(a)).add(new int[]{names.indexOf(b), w});
    }

    public static void main(String[] args) {
        for (int i = 0; i < names.length(); i++) adj.add(new ArrayList<>());
        edge('S', 'A', 1); edge('S', 'B', 4); edge('A', 'B', 2); edge('A', 'C', 6);
        edge('B', 'C', 3); edge('B', 'D', 7); edge('C', 'D', 1); edge('C', 'T', 8); edge('D', 'T', 3);

        int n = names.length();
        int[] dist = new int[n], parent = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        Arrays.fill(parent, -1);
        dist[0] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>((x, y) -> x[0] != y[0] ? Integer.compare(x[0], y[0]) : Integer.compare(x[1], y[1]));
        pq.add(new int[]{0, 0});                                  // {distance, vertex}
        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int d = top[0], u = top[1];
            if (d > dist[u]) {
                System.out.println("  skip stale (" + d + ", " + names.charAt(u) + ")");
                continue;
            }
            System.out.println("settle " + names.charAt(u) + " at " + d);
            for (int[] e : adj.get(u)) {
                int v = e[0], w = e[1];
                if (d + w < dist[v]) {
                    System.out.println("  " + names.charAt(v) + ": " + (dist[v] == Integer.MAX_VALUE ? "inf" : String.valueOf(dist[v])) + " -> " + (d + w));
                    dist[v] = d + w;
                    parent[v] = u;
                    pq.add(new int[]{dist[v], v});
                }
            }
        }
        List<Character> path = new ArrayList<>();
        for (int v = names.indexOf('T'); v != -1; v = parent[v]) path.add(names.charAt(v));
        Collections.reverse(path);
        System.out.println("shortest S -> T: " + path + " with length " + dist[names.indexOf('T')]);
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.PriorityQueue;

public class MinimumSpanningTree {
    static String names = "ABCDEF";
    static int[][] edges = {   // {u, v, weight}
        {0, 1, 4}, {0, 2, 3}, {1, 2, 2}, {1, 3, 5}, {2, 3, 4}, {2, 4, 6}, {3, 4, 1}, {3, 5, 7}, {4, 5, 3}
    };
    static int[] parent;

    static int find(int x) { return parent[x] == x ? x : (parent[x] = find(parent[x])); }

    static String name(int[] e) { return names.charAt(e[0]) + "-" + names.charAt(e[1]) + "(" + e[2] + ")"; }

    public static void main(String[] args) {
        int n = names.length();
        int[][] sorted = edges.clone();
        Arrays.sort(sorted, (a, b) -> a[2] != b[2] ? Integer.compare(a[2], b[2]) : Integer.compare(a[0] * 10 + a[1], b[0] * 10 + b[1]));
        parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        int total = 0, used = 0;
        System.out.println("Kruskal:");
        for (int[] e : sorted) {
            if (used == n - 1) break;
            int ru = find(e[0]), rv = find(e[1]);
            if (ru == rv) {
                System.out.println("  skip " + name(e) + ": would close a cycle");
                continue;
            }
            parent[ru] = rv;                         // union the two components
            total += e[2];
            used++;
            System.out.println("  take " + name(e));
        }
        System.out.println("  total weight " + total);

        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e);
            adj.get(e[1]).add(new int[]{e[1], e[0], e[2]});
        }
        boolean[] inTree = new boolean[n];
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[2] != b[2] ? Integer.compare(a[2], b[2])
                : a[1] != b[1] ? Integer.compare(a[1], b[1]) : Integer.compare(a[0], b[0]));
        inTree[0] = true;
        pq.addAll(adj.get(0));
        total = 0;
        System.out.println("Prim from A:");
        while (!pq.isEmpty()) {
            int[] e = pq.poll();
            if (inTree[e[1]]) continue;              // both ends already in the tree
            inTree[e[1]] = true;
            total += e[2];
            System.out.println("  add " + names.charAt(e[1]) + " via " + name(e));
            for (int[] next : adj.get(e[1])) if (!inTree[next[1]]) pq.add(next);
        }
        System.out.println("  total weight " + total);
    }
}
